 intro.innerHTML=`<div class="questCoverArt"></div><div class="questCoverShade"></div><div class="questCoverText"><p class="questEyebrow">山河重光　/　沉浸式历史作业</p><p class="coverChapter">第一章 / 胜利的时刻</p><h1>亲历·南京受降</h1><p class="questLead">1945年9月9日，你来到南京受降现场。<br>环顾现场，听一段历史，再用答案完成你的胜利档案。</p><div class="questRoute"><span>01 沉浸讲述</span><i>→</i><span>02 章节校验</span><i>→</i><span>03 真题挑战</span><i>→</i><span>04 通关交作业</span></div><label class="questName">作业署名 <input maxlength="24" autocomplete="off" placeholder="输入姓名或昵称（可选）"></label><div class="questCoverActions"><button data-q="start" class="questPrimary"></button><button data-q="fresh">重新挑战</button></div><p class="questFine">约5—8分钟 · 八年级抗战单元 · AI情境辅助学习 · 电脑 / 平板 · 可离线体验</p><p class="questFine">通关后导出学习报告，作为游戏作业交给老师。</p></div><div class="questCoverStamp"><span>中国战区受降</span><strong>1945</strong>09 / 09 · 南京<br><span>收集证据，让历史有迹可循</span></div>`;
 document.body.append(intro);intro.hidden=true;
 intro.querySelector('.questCoverArt').style.backgroundImage='url("'+COVER+'")';
 intro.querySelector('input').value=state.name==='体验同学'?'':state.name;
 intro.querySelector('[data-q=start]').textContent=state.started?'继续我的章节 →':'进入历史现场 →';
 const hud=document.createElement('aside');hud.id='questHud';hud.hidden=true;m.append(hud);
 const panel=document.createElement('section');panel.id='questPanel';panel.hidden=true;panel.setAttribute('aria-label','任务档案');m.append(panel);
 const toast=document.createElement('div');toast.id='questToast';toast.setAttribute('role','status');m.append(toast);let toastTimer;
 function notify(text){toast.textContent=text;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),3500);}
 function pause(){if(!window.nanjingImmersiveInfo().paused)m.querySelector('[data-action=pause]').click();}
 function hide(){panel.hidden=true;m.classList.remove('lecturePanelOpen');lecture.querySelector('[data-l=next]')?.focus();}
 function show(title,body){if(typeof film!=='undefined')stopFilm();pause();stopVoice();m.classList.add('lecturePanelOpen');panel.hidden=false;panel.innerHTML=`<article><header><div><p class="questEyebrow">胜利档案 / 南京受降</p><h2>${title}</h2></div><button data-q="close" aria-label="返回现场">×</button></header>${body}</article>`;panel.querySelector('[data-q=close]').onclick=hide;panel.querySelector('button')?.focus();}
 function renderHud(){const count=state.clues.length;
  hud.innerHTML=`<p class="questEyebrow">你的任务 · 胜利档案</p><h2>${state.completed?'任务已通关':'把胜利的日期还给历史'}</h2><ol><li class="${count===3?'done':''}">寻找三处线索 <b>${count}/3</b></li><li class="${state.timeline?'done':''}">重建事件时间线 <b>${state.timeline?'✓':count===3?'可挑战':'待解锁'}</b></li><li class="${state.exam?'done':''}">完成史料辨析 <b>${state.exam?'✓':state.timeline?'可挑战':'待解锁'}</b></li><li class="${state.completed?'done':''}">完成选择与连线</li></ol><button class="questPrimary" data-q="next">${state.completed?'查看通关报告':count<3?'查看线索任务':!state.timeline?'挑战时间线':!state.exam?'进入试题关':'完成通关档案'} →</button><button data-q="notebook">线索手册</button><small>拖动环视找热点，或从手册查看线索。</small>`;
  hud.querySelector('[data-q=next]').onclick=next;hud.querySelector('[data-q=notebook]').onclick=notebook;
  m.querySelectorAll('.surrenderHotspot').forEach((b,i)=>b.classList.toggle('questCollected',state.clues.includes(i)));
 }
 function next(){if(state.timeline&&state.exam)report();else if(!state.timeline)timeline();else exam();}

 function notebook(){show('现场线索手册',`<p>你的身份是历史研学者。先观察，再依据材料判断，最后用选择与连线检验掌握情况。</p><div class="questClueList">${clues.map((c,i)=>`<button data-clue="${i}"><b>${state.clues.includes(i)?'✓ 已收集':'○ 待寻找'}</b><span>${c.title}</span><small>查看史料与出处 →</small></button>`).join('')}</div><p class="questSource">三条史料卡含会场旧照、两份投降文书及签署照片。图片可离线查看，出处链接需联网。</p>`);panel.querySelectorAll('[data-clue]').forEach(b=>b.onclick=()=>collect(Number(b.dataset.clue)));}
 function collect(i){const c=clues[i];show(c.title,`<figure class="detailArt"><img src="${DETAILS[i]}" alt="${c.title}的AI情境局部图"><figcaption>AI情境局部图 · 请以文字史料核实事实</figcaption></figure><p class="questClueText">${c.text}</p><div class="questCoach"><b>研学提示</b><p>${c.tip}</p></div><button class="questPrimary" data-q="collect">${state.clues.includes(i)?'已在手册中 · 返回现场':'收进我的线索手册'} →</button><p class="questSource">史实来源：南京市地方志工作办公室；史料方法提示为原创教学设计。</p>`);panel.querySelector('[data-q=collect]').onclick=()=>{if(!state.clues.includes(i)){state.clues.push(i);save();}hide();renderHud();notify(state.clues.length===3?'三条线索已齐，时间线挑战已解锁！':`线索 +1 · 已收集 ${state.clues.length}/3`);};}
 m.querySelectorAll('[data-hotspot]').forEach(b=>{b.onclick=()=>window.nanjingWatchHallPerspective?.(b.dataset.povRole);});
 function attempt(kind,answer,correct){state.attempts.push({kind,answer,correct,at:new Date().toISOString()});save();}
 function timeline(){
  const dates=['1945年8月15日','1945年9月2日','1945年9月9日'];
  const places=['日本 · 广播宣布','东京湾 · 密苏里号','南京 · 原中央军校大礼堂'];
  const events=['宣布无条件投降','向盟国签署投降书','中国战区受降仪式'];
  let links=Array.isArray(state.matching)?state.matching.map(x=>({...x})):[{place:null,event:null},{place:null,event:null},{place:null,event:null}];
  let selected=0,checked=false;
  show('第一关 · 把胜利的时刻连起来',`<p class="questTag">原创连线题 · 日期 → 地点 / 场合 → 事件</p><p>先选左侧日期，再点中间地点，最后点右侧事件。选中日期后可以重新连接，每项只用一次。</p><div class="matchBoard"><svg class="matchLines" aria-hidden="true"></svg><div class="matchColumn"><h3>日期</h3>${dates.map((t,i)=>`<button data-date="${i}"><small>0${i+1}</small>${t}</button>`).join('')}</div><div class="matchColumn"><h3>地点 / 场合</h3>${[1,2,0].map(i=>`<button data-place="${i}">${places[i]}</button>`).join('')}</div><div class="matchColumn"><h3>历史事件</h3>${[2,0,1].map(i=>`<button data-event="${i}">${events[i]}</button>`).join('')}</div></div><div class="matchPrompt" role="status"></div><div class="questFeedback" aria-live="polite"></div><div class="questActions"><button data-match="reset">清空连线</button><button class="questPrimary" data-match="check">核对连线</button></div><p class="questSource">依据南京市地方志工作办公室相关史实设计；本题为原创情境练习。</p>`);
  const board=panel.querySelector('.matchBoard'),svg=board.querySelector('svg');
  const colors=['#6f8875','#a58756','#64868e'];
  function saveLinks(){state.matching=links.map(x=>({...x}));save();}
  function draw(){if(panel.hidden||!board.isConnected)return;const box=board.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);svg.innerHTML='';
   function path(a,b,row){const x=a.getBoundingClientRect(),y=b.getBoundingClientRect(),x1=x.right-box.left,y1=x.top+x.height/2-box.top,x2=y.left-box.left,y2=y.top+y.height/2-box.top;const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',`M${x1},${y1} C${x1+(x2-x1)*.55},${y1} ${x2-(x2-x1)*.55},${y2} ${x2},${y2}`);p.setAttribute('stroke',checked?(links[row].place===row&&links[row].event===row?'#728866':'#b37055'):colors[row]);p.setAttribute('stroke-width',row===selected?'3':'2');p.setAttribute('fill','none');svg.append(p);}
   links.forEach((v,i)=>{if(v.place!==null){path(board.querySelector(`[data-date="${i}"]`),board.querySelector(`[data-place="${v.place}"]`),i);if(v.event!==null)path(board.querySelector(`[data-place="${v.place}"]`),board.querySelector(`[data-event="${v.event}"]`),i);}});
  }
  function paint(){board.querySelectorAll('button').forEach(b=>{b.classList.remove('matchSelected','matchLinked');b.setAttribute('aria-pressed','false');});const v=links[selected];const buttons=[board.querySelector(`[data-date="${selected}"]`),v.place===null?null:board.querySelector(`[data-place="${v.place}"]`),v.event===null?null:board.querySelector(`[data-event="${v.event}"]`)];buttons.filter(Boolean).forEach(b=>{b.classList.add('matchSelected');b.setAttribute('aria-pressed','true');});links.forEach(v=>{if(v.place!==null)board.querySelector(`[data-place="${v.place}"]`).classList.add('matchLinked');if(v.event!==null)board.querySelector(`[data-event="${v.event}"]`).classList.add('matchLinked');});panel.querySelector('.matchPrompt').textContent=`正在连接：${dates[selected]} · ${v.place===null?'请选择中间地点':v.event===null?'请选择右侧事件':'已连接，可切换日期或修改本条'}`;requestAnimationFrame(draw);}
  function edit(){checked=false;panel.querySelector('.questFeedback').textContent='';saveLinks();paint();}
  board.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.date);paint();});
  board.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.place);links.forEach((v,i)=>{if(i!==selected&&v.place===id)v.place=null;});links[selected].place=id;edit();});
  board.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{if(links[selected].place===null){panel.querySelector('.matchPrompt').textContent='先选择中间地点，再连接右侧事件。';return;}const id=Number(b.dataset.event);links.forEach((v,i)=>{if(i!==selected&&v.event===id)v.event=null;});links[selected].event=id;edit();});
  panel.querySelector('[data-match=reset]').onclick=()=>{links=[{place:null,event:null},{place:null,event:null},{place:null,event:null}];selected=0;edit();};
  panel.querySelector('[data-match=check]').onclick=()=>{if(links.some(v=>v.place===null||v.event===null)){panel.querySelector('.questFeedback').textContent='还有未完成的连线，请把三个日期的地点与事件都连齐。';return;}const ok=links.every((v,i)=>v.place===i&&v.event===i);attempt('matching',links.map((v,i)=>({date:dates[i],place:places[v.place],event:events[v.event]})),ok);checked=true;draw();panel.querySelector('.questFeedback').textContent=ok?'全部正确！宣布投降 → 东京湾签字 → 南京受降，三个时刻各有对应。':'有连线需要调整。棕红色链条存在错误，请对照讲述核实日期、地点与事件，再点日期修改。';if(ok){state.timeline=true;save();board.querySelectorAll('button').forEach(b=>b.disabled=true);panel.querySelector('[data-match=reset]').disabled=true;const btn=panel.querySelector('[data-match=check]');btn.textContent='进入选择题 →';btn.onclick=exam;}};
  const observer=new ResizeObserver(draw);observer.observe(board);const cleanup=new MutationObserver(()=>{if(!board.isConnected){observer.disconnect();cleanup.disconnect();}});cleanup.observe(panel,{childList:true});paint();
 }

 function exam(){if(!state.timeline)return timeline();show('第二关 · 史实与评价',`<p class="questTag">真题考点改编 · 2023辽宁大连历史第5题（公开汇编收录）</p><p>你要给档案写说明。下列哪一句是在评价历史意义，而不是叙述一个具体史实？</p><div class="questChoices">${['1936年12月，西安事变发生。','七七事变爆发后，中国守军奋起抵抗。','百团大战鼓舞了争取抗战胜利的信心。','1945年9月9日，南京举行中国战区受降仪式。'].map((t,i)=>`<button data-exam="${i}"><b>${'ABCD'[i]}</b> ${t}</button>`).join('')}</div><div class="questFeedback" aria-live="polite"></div><button data-q="exam-next" class="questPrimary" hidden>生成通关作业 →</button><p class="questSource">依据公开汇编第1页第5题改写题干及部分选项，非原题全文。<a href="${source}#page=1" target="_blank" rel="noopener">查看收录出处 ↗</a></p>`);
  panel.querySelectorAll('[data-exam]').forEach(b=>b.onclick=()=>{const answer=Number(b.dataset.exam),ok=answer===2;attempt('exam',answer,ok);panel.querySelectorAll('[data-exam]').forEach(x=>{x.classList.remove('wrong','correct');x.setAttribute('aria-pressed',String(x===b));});b.classList.add(ok?'correct':'wrong');panel.querySelector('.questFeedback').textContent=ok?'正确。“鼓舞信心”判断了战役的作用和意义，属于历史评价。日期、地点、人物行动的具体叙述属于史实。':'再比较一下：这句话在交代发生了什么。请找出对事件作用或意义作出判断的一项。';if(ok){state.exam=true;save();renderHud();panel.querySelector('[data-q=exam-next]').hidden=false;panel.querySelectorAll('[data-exam]').forEach(x=>x.disabled=true);}});panel.querySelector('[data-q=exam-next]').onclick=finishSimple;}
 function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);notify('报告已导出，请把下载文件交给老师。');}
 function finishSimple(){if(!state.timeline||!state.exam)return next();if(!state.completed)state.completed=new Date().toISOString();save();renderHud();report();}
 function results(){return {title:'南京受降 · 选择与连线通关作业',version,name:state.name,started:state.started,completed:state.completed,chaptersRead:[...(state.viewed||[])],objectiveQuestions:2,mastered:[state.timeline,state.exam].filter(Boolean).length,firstAttemptCorrect:['matching','exam'].filter(k=>state.attempts.find(a=>a.kind===k)?.correct).length,attempts:state.attempts,sources:[archive,source],identities:fiveRoles.map(r=>({id:r.id,name:identityNames[r.id],watched:povWatched(r.id),done:roleFinished(r.id)})),notice:'本机离线生成的学习记录；四视角体验与综合练习分别记录。'};}
 function report(){const r=results();show('学习报告 · 实际完成记录',`<div class="questMedal">✓</div><p class="questReportName">${escape(r.name)} · 南京受降研学者</p><div class="questStats"><span><b>${r.chaptersRead.length}/3</b>章节研读</span><span><b>${r.mastered}/2</b>最终掌握</span><span><b>${r.firstAttemptCorrect}/2</b>首次答对</span></div><p>综合练习与四个身份分别计数，未体验的身份不会自动完成。</p><div class="simpleComplete"><span>${r.mastered>0&&state.timeline?"✓":"○"} 日期 · 地点 · 事件连线</span><span>${state.exam?"✓":"○"} 史实与评价选择题</span></div><p class="questSource">综合练习共两题，另记录剧情任务的7项判断；本轮作答共${r.attempts.length}次。</p><div class="questActions"><button class="questPrimary" data-q="export">导出通关作业（HTML）</button><button data-q="json">导出学习记录（JSON）</button><button data-q="restart" title="清空本轮答题记录，重新演示">重新开始 ↺</button><button data-q="map">返回地图 →</button></div><p class="questSource">${r.notice}</p>`);
  const answerText=a=>a.kind.startsWith('historyTask:')?a.answer.question+' → '+a.answer.answer:a.kind==='matching'?a.answer.map(x=>`${x.date} → ${x.place} → ${x.event}`).join('\n'):'ABCD'[Number(a.answer)];
  const html=()=>`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>南京受降通关作业</title><style>body{font:14.4px/1.9 system-ui;max-width:900px;margin:40px auto;padding:25px;color:#263d30}h1{font-family:serif}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccd0be;padding:12px;text-align:left;white-space:pre-wrap}small{color:#66735d}</style></head><body><h1>南京受降 · 通关作业</h1><p>署名：${escape(r.name)}</p><p>章节研读${r.chaptersRead.length}/3 · 最终掌握${r.mastered}/2 · 首次答对${r.firstAttemptCorrect}/2</p><p>开始：${escape(r.started)}<br>完成：${escape(r.completed)}</p><h2>四视角体验</h2><ul>${r.identities.map(x=>`<li>${escape(x.name)}：${x.watched?"已观看":"未观看"} · ${x.done?"任务已完成":"任务待完成"}</li>`).join('')}</ul><h2>角色交流记录</h2><ul>${(r.roleExperience?.dialogues||[]).map(d=>`<li>${escape(d.label)}：${escape(d.choice)}</li>`).join('')}</ul><h2>学习过程</h2><table><tr><th>题型</th><th>我的答案</th><th>结果</th></tr>${r.attempts.map(a=>`<tr><td>${a.kind.startsWith('historyTask:')?'剧情学习任务':a.kind==='matching'?'三组连线':'选择题'}</td><td>${escape(answerText(a))}</td><td>${a.correct?'正确':'重试'}</td></tr>`).join('')}</table><h2>学习依据</h2><p>连线题为依据南京市地方志相关史实编写的原创练习：<a href="${archive}">史实来源</a>。选择题为2023辽宁大连第5题考点改编：<a href="${source}#page=1">公开收录出处</a>。</p><small>${escape(r.notice)}</small></body></html>`;
  panel.querySelector('[data-q=restart]').onclick=restartDemo;
  panel.querySelector('[data-q=map]').onclick=()=>back.click();
  panel.querySelector('[data-q=export]').onclick=()=>download('南京受降_通关作业.html',html(),'text/html;charset=utf-8');panel.querySelector('[data-q=json]').onclick=()=>download('南京受降_学习记录.json',JSON.stringify(r,null,2),'application/json;charset=utf-8');
 }

 function start(fresh=false){if(fresh)state=blank();state.name=intro.querySelector('input').value.trim()||'体验同学';if(!state.started)state.started=new Date().toISOString();save();intro.hidden=true;document.body.classList.add('questPlaying');hud.hidden=false;openScene();pause();renderHud();openLecture(fresh);if(state.completed)report();}
 intro.querySelector('[data-q=start]').onclick=()=>start();intro.querySelector('[data-q=fresh]').onclick=()=>start(true);
 const back=m.querySelector('[data-action=back]'),oldBack=back.onclick;back.textContent='← 返回地图';back.onclick=()=>{stopLecture();hide();oldBack();intro.hidden=true;hud.hidden=true;document.body.classList.remove('questPlaying');intro.querySelector('[data-q=start]').textContent='从头进入本章 →';};
 const launch=document.createElement('button');launch.id='questResume';launch.textContent='进入本章 →';launch.onclick=()=>start();document.body.append(launch);
 m.addEventListener('keydown',e=>{if(!panel.hidden){if(e.key==='Tab'){const items=[...panel.querySelectorAll('button:not([hidden]):not(:disabled),a,textarea')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();hide();}else if(e.key.startsWith('Arrow'))e.stopImmediatePropagation();}},true);
 m.querySelector('[data-action=book]').onclick=notebook;m.querySelector('[data-action=quiz]').onclick=next;m.querySelector('[data-action=quiz]').textContent='当前挑战 →';m.querySelector('[data-action=book]').textContent='史料手册';
  const chapters=[{"title": "这一刻，山河重光", "tag": "01 / 仪式现场", "date": "1945 · 09 · 09", "step": 0, "lines": ["一九四五年九月九日上午九时，南京。中国战区日军投降签字仪式，在原中央军校大礼堂举行。", "请环顾这座大厅。受降席与投降席相对而设，一份降书，见证了艰苦抗战之后的历史时刻。", "今天，你将以历史研学者的身份走进这个现场。先看清发生了什么，再思考我们应该怎样记住它。"], "audio": [window.njAsset("njAsset-7ca1d087871b6f12ec6e"), window.njAsset("njAsset-ebcfa8d732a12b0ab911"), window.njAsset("njAsset-6a22c6a43d46ad5f0c32")]}, {"title": "三次日期，一段历史", "tag": "02 / 签署降书", "date": "1945 · 八月—九月", "step": 1, "lines": ["八月十五日，日本宣布无条件投降。九月二日，日本在东京湾的密苏里号上，向盟国签署投降书。", "九月九日，南京举行中国战区受降仪式。冈村宁次代表日军签署降书，何应钦代表中国战区接受投降。", "宣布投降，东京湾签字，南京受降。三个日期，分别对应不同的事件与范围，不能混为一谈。"], "audio": [window.njAsset("njAsset-991dd5641017c8192249"), window.njAsset("njAsset-b8abc3f680037158be62"), window.njAsset("njAsset-7aa7fa517d79be7b97e4")]}, {"title": "让证据，留下答案", "tag": "03 / 铭记胜利", "date": "铭记历史 · 珍爱和平", "step": 2, "lines": ["从一九三一年到一九四五年，十四年艰苦抗战。胜利来之不易，和平值得珍惜。", "眼前的大厅，是人工智能辅助创作的历史情境插画。它帮助我们想象现场，却不能代替档案、史料照片与严谨的研究。", "会场的观察先告一段落。带上你的现场记录，到记者桌看看：稿子里的说法，能不能得到观察记录和档案材料的支持？"], "audio": [window.njAsset("njAsset-7b39261a33ec1fe55398"), window.njAsset("njAsset-e5a7cd6e84edcf18d04e"), window.njAsset("njAsset-voice-hall_ending-1332")]}];
 const lecture=document.createElement('section');lecture.id='lecture';lecture.setAttribute('aria-label','南京受降沉浸讲述');
 lecture.innerHTML=`<header class="lectureHeader"><div class="lectureBrand">山河重光 <span>南京受降 / 叙事课堂</span></div><nav><button data-l="chapters">章节</button><button data-l="book">史料</button><button data-l="fullscreen">全屏</button><button data-l="replay">重播此段</button><button data-l="restart" title="清空本轮进度，从第一句旁白开始">重新开始</button><button data-l="voice" aria-pressed="true">配音：开</button><button data-l="back">返回地图</button></nav></header><div class="lectureHeading"><p class="lectureDate"></p><h1></h1><p class="lectureKicker"></p></div><div class="lectureChapters" hidden></div><footer class="lectureDialogue"><div class="lectureMeta"><b>历史讲述者</b><span>教学旁白 · 非历史人物原话</span><small class="lectureCounter"></small></div><p class="lectureSubtitle" aria-live="polite"></p><div class="lectureBottom"><span class="lectureStatus"></span><div><button data-l="prev">← 上一句</button><button data-l="play">暂停配音</button><button data-l="next">继续讲述 →</button></div></div><div class="lectureRail"></div></footer><div class="lectureCredit">AI 历史情境插画 · 非史料照片或精确复原 <span>拖动环视 · 滚轮缩放 · WASD 转向</span></div>`;
 m.append(lecture);const voicePlayer=new Audio();voicePlayer.preload='auto';let voiceOn=true,voiceToken=0,chapter=0,line=0,active=false,audioIssue=false;
 const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function stopVoice(){voiceToken++;voicePlayer.pause();}
 function storeLecture(){state.chapter=chapter;state.line=line;save();}
 function markViewed(){if(!state.viewed.includes(chapter))state.viewed.push(chapter);if(!state.clues.includes(chapter))state.clues.push(chapter);save();renderRail();}
 function renderRail(){lecture.querySelector('.lectureRail').innerHTML=chapters.map((c,i)=>`<button data-chapter="${i}" class="${i===chapter?'active':''} ${state.viewed.includes(i)?'viewed':''}"><small>0${i+1}</small> ${c.tag.split(' / ')[1]} <span>${state.viewed.includes(i)?'✓':''}</span></button>`).join('');lecture.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>chooseChapter(Number(b.dataset.chapter)));}
 function setPlayText(){lecture.querySelector('[data-l=play]').textContent=!voiceOn?'配音已关闭':voicePlayer.paused?'播放本句':'暂停配音';}
 function playVoice(){stopVoice();if(!active||!voiceOn||!panel.hidden)return;const token=voiceToken;voicePlayer.src=chapters[chapter].audio[line];audioIssue=false;const result=voicePlayer.play();if(result)result.then(()=>{if(token===voiceToken){setPlayText();lecture.querySelector('.lectureStatus').textContent='正在讲述 · 可拖动画面环顾现场';}}).catch(()=>{if(token!==voiceToken)return;audioIssue=true;lecture.querySelector('.lectureStatus').textContent='点击“播放本句”开启配音，也可阅读字幕继续';setPlayText();});}
 function paintLecture(play=true){const c=chapters[chapter];storeLecture();lecture.querySelector('.lectureDate').textContent=c.date;lecture.querySelector('.lectureHeading h1').textContent=c.title;lecture.querySelector('.lectureKicker').textContent=c.tag+'　/　中国战区受降';lecture.querySelector('.lectureSubtitle').textContent=c.lines[line];lecture.querySelector('.lectureCounter').textContent=`0${chapter+1} / 03 · ${line+1} / ${c.lines.length}`;lecture.querySelector('[data-l=prev]').disabled=chapter===0&&line===0;lecture.querySelector('[data-l=next]').textContent=chapter===2&&line===2?'进入章节校验 →':line===2?'下一段历史 →':'继续讲述 →';lecture.querySelector('.lectureStatus').textContent=voiceOn?'准备讲述…':'配音已关闭 · 阅读字幕后继续';renderRail();if(play)playVoice();setPlayText();}
 function chooseChapter(index){stopVoice();chapter=index;line=0;lecture.querySelector('.lectureChapters').hidden=true;m.querySelector(`[data-step="${index}"]`).click();paintLecture();}
 function advanceLecture(){if(line<chapters[chapter].lines.length-1){line++;paintLecture();return;}markViewed();if(chapter<2){chooseChapter(chapter+1);return;}if(state.viewed.length<3){const missing=[0,1,2].find(i=>!state.viewed.includes(i));chooseChapter(missing);notify('补完这一段，再进入校验。');return;}stopVoice();timeline();}
 voicePlayer.onended=()=>{if(!active||!panel.hidden)return;if(line<2){line++;paintLecture();}else{markViewed();lecture.querySelector('.lectureStatus').textContent=chapter===2?'三段讲述完成，点击右侧前往记者记录桌':'本段讲述完毕，点击右侧进入下一段';setPlayText();}};
 voicePlayer.onerror=()=>{audioIssue=true;lecture.querySelector('.lectureStatus').textContent='本句配音未能播放，可阅读字幕继续';setPlayText();};
 function openLecture(fresh){active=true;state.viewed=state.viewed||[];chapter=fresh?0:Math.max(0,Math.min(2,state.chapter||0));line=fresh?0:Math.max(0,Math.min(2,state.line||0));m.classList.add('lecturePlaying');m.querySelector(`[data-step="${chapter}"]`).click();paintLecture();}
 function stopLecture(){active=false;stopVoice();m.classList.remove('lecturePlaying');}
 lecture.querySelector('[data-l=next]').onclick=advanceLecture;
 lecture.querySelector('[data-l=prev]').onclick=()=>{if(line>0){line--;paintLecture();}else if(chapter>0){chooseChapter(chapter-1);line=2;paintLecture();}};
 lecture.querySelector('[data-l=play]').onclick=()=>{if(!voiceOn){voiceOn=true;lecture.querySelector('[data-l=voice]').textContent='配音：开';lecture.querySelector('[data-l=voice]').setAttribute('aria-pressed','true');}if(voicePlayer.paused)playVoice();else{stopVoice();setPlayText();}};
 lecture.querySelector('[data-l=voice]').onclick=()=>{voiceOn=!voiceOn;lecture.querySelector('[data-l=voice]').textContent=voiceOn?'配音：开':'配音：关';lecture.querySelector('[data-l=voice]').setAttribute('aria-pressed',String(voiceOn));if(voiceOn)playVoice();else{stopVoice();lecture.querySelector('.lectureStatus').textContent='配音已关闭 · 阅读字幕后继续';setPlayText();}};
 lecture.querySelector('[data-l=replay]').onclick=()=>{line=0;paintLecture();};
 lecture.querySelector('[data-l=back]').onclick=()=>m.querySelector('[data-action=back]').click();
 lecture.querySelector('[data-l=book]').onclick=notebook;
 lecture.querySelector('[data-l=chapters]').onclick=()=>{const box=lecture.querySelector('.lectureChapters');box.hidden=!box.hidden;box.innerHTML=chapters.map((c,i)=>`<button data-go="${i}"><small>${c.tag}</small><strong>${c.title}</strong></button>`).join('')+'<button data-go="quiz"><small>04 / 章节校验</small><strong>用你的答案完成档案 →</strong></button>';box.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{box.hidden=true;if(b.dataset.go==='quiz')next();else chooseChapter(Number(b.dataset.go));});};
 lecture.querySelector('[data-l=fullscreen]').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await m.requestFullscreen();}catch{notify('当前窗口不支持全屏，可继续正常学习。');}};
 m.addEventListener('close',stopLecture);m.addEventListener('cancel',e=>{e.preventDefault();e.stopImmediatePropagation();if(!panel.hidden)hide();else m.querySelector('[data-action=back]').click();},true);document.addEventListener('visibilitychange',()=>{if(document.hidden){stopVoice();setPlayText();}});
 window.nanjingLectureInfo=()=>({voiceSource:"breeze-news-male-2005",chapter,line,viewed:[...(state.viewed||[])],voiceOn,playing:!voicePlayer.paused,audioIssue,active,panel:!panel.hidden,audioTime:voicePlayer.currentTime,audioDuration:voicePlayer.duration});

 function restartDemo(){
  stopLecture();hide();clearTimeout(toastTimer);toast.classList.remove('visible');
  lecture.querySelector('.lectureChapters').hidden=true;
  voiceOn=true;lecture.querySelector('[data-l=voice]').textContent='配音：开';lecture.querySelector('[data-l=voice]').setAttribute('aria-pressed','true');
  m.querySelector('[data-action=replay]').click();start(true);
  lecture.querySelector('[data-l=next]').focus();
 }
 lecture.querySelector('[data-l=restart]').onclick=restartDemo;

 window.openNanjingImmersive=()=>start();
