const roleLayer=document.createElement('section');roleLayer.id='njRoleScene';roleLayer.hidden=true;m.append(roleLayer);
roleLayer.addEventListener('pointermove',e=>{if(!roleMotion||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const art=roleLayer.querySelector('.njRoleArt');if(art)art.style.translate=((e.clientX/innerWidth-.5)*.7)+'% '+((e.clientY/innerHeight-.5)*.5)+'%';});
const sceneLabel=document.createElement('div');sceneLabel.id='njSceneLabel';m.append(sceneLabel);
let roleStage='hall',roleMotion=true;
state.roleLog=state.roleLog||[];
function logRole(id,label,choice){state.roleLog=state.roleLog||[];if(!state.roleLog.some(r=>r.id===id))state.roleLog.push({id,label,choice,at:new Date().toISOString()});save();}
function labelScene(text){sceneLabel.textContent=text;}
function hallLabel(){labelScene(['南京 · 原中央军校大礼堂\n（随行观察员 · 受降席视角）','南京 · 签署投降书现场\n（随行观察员 · 降书观察视角）','南京 · 观礼区\n（随行观察员 · 历史见证视角）'][chapter]);}
function leaveRole(){roleLayer.hidden=true;m.classList.remove('njRoleActive');roleStage='hall';hallLabel();}
function enterHall(){state.roleStage='hall';save();leaveRole();openLecture(false);}
function roleShell(stage){
 stopVoice();panel.hidden=true;m.classList.remove('lecturePanelOpen');roleStage=stage;state.roleStage=stage;save();m.classList.add('njRoleActive');roleLayer.hidden=false;
 const outside=stage==='entrance';labelScene(outside?'南京 · 受降会场外\n（随行观察员视角）':'胜利消息传来 · 南京街头\n（普通市民视角）');
 roleLayer.innerHTML=`<div class="njRoleArt"></div><div class="njRoleVignette"></div><header class="njRoleHeader"><button data-r="map">← 返回地图</button><span>山河重光 / 南京受降</span><button data-r="motion" aria-pressed="true">动效：开</button><button data-r="restart">重新开始</button></header><nav class="njRoute" aria-label="体验流程"><span class="${outside?'active':''}">01 会场外交流</span><span>02 入场见证</span><span class="${outside?'':'active'}">03 胜利消息</span><span>04 连线与作业</span></nav><div class="njRoleTargets"></div><section class="njDialogue"><div class="njSpeaker"><b>${outside?'随行观察员':'街头见证者'}</b><span>教学角色 · 对话为教学虚构</span><small>${outside?'入场准备':'仪式结束后的消息传播'}</small></div><h2>${outside?'入场前，先把任务问清楚':'胜利的消息，传向街头'}</h2><p class="njDialogueText">${outside?'你来到南京受降会场外。向工作人员确认今天的仪式，再向记者请教如何记录历史。':'受降仪式结束后，消息通过广播等方式传播。听一听消息，再和市民聊聊：这场胜利意味着什么？'}</p><div class="njReplies"></div><div class="njSceneActions"><span class="njProgress"></span><button class="njPrimary" data-r="continue">${outside?'进入受降会场 →':'整理胜利时间线 →'}</button></div></section><small class="njRoleCredit">AI情境重构 · ${outside?'会场外交流为教学设计':'庆祝场景为概括性重构，不代表全国各地在同一时刻的实况'}</small>`;
 roleLayer.querySelector('.njRoleArt').style.backgroundImage=`url("${roleArt[outside?'entrance':'celebration']}")`;
 const targets=roleLayer.querySelector('.njRoleTargets');
 targets.innerHTML=outside?'<button data-person="orderly" style="left:23%;top:40%">＋ 工作人员<span>确认仪式</span></button><button data-person="reporter" style="left:72%;top:43%">＋ 随行记者<span>领受记录任务</span></button>':'<button data-person="radio" style="left:78%;top:43%">＋ 街头广播<span>收听受降消息</span></button><button data-person="citizen" style="left:30%;top:42%">＋ 庆祝的市民<span>谈谈胜利与和平</span></button>';
 if(!outside){const figure=document.createElement('div');figure.className='njClapping';figure.setAttribute('aria-label','市民鼓掌连帧动画');figure.style.backgroundImage=`url("${roleArt.applause}")`;roleLayer.insertBefore(figure,roleLayer.querySelector('.njDialogue'));}
 roleLayer.querySelector('[data-r=map]').onclick=()=>back.click();roleLayer.querySelector('[data-r=restart]').onclick=()=>{restartDemo();showEntrance();};
 roleLayer.querySelector('[data-r=motion]').onclick=e=>{roleMotion=!roleMotion;m.classList.toggle('njMotionOff',!roleMotion);e.currentTarget.textContent='动效：'+(roleMotion?'开':'关');e.currentTarget.setAttribute('aria-pressed',String(roleMotion));};
 roleLayer.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>roleTalk(b.dataset.person));
 roleLayer.querySelector('[data-r=continue]').onclick=()=>{if(outside){if(!hasRole('orderly')||!hasRole('reporter')){roleLayer.querySelector('.njDialogueText').textContent='先点击两位人物完成入场交流，带着日期、地点和观察任务进入会场。';return;}state.entranceDone=true;save();enterHall();}else{if(!hasRole('radio')||!hasRole('citizen')){roleLayer.querySelector('.njDialogueText').textContent='先收听广播、完成市民交流，再把刚刚见证的历史整理成时间线。';return;}state.celebrationDone=true;save();leaveRole();baseTimeline();labelScene('胜利档案 · 日期—地点—事件\n（随行观察员 · 时间线整理）');}};
 const nameButton=document.createElement('button');nameButton.textContent='学习署名';nameButton.onclick=()=>{const replies=roleLayer.querySelector('.njReplies');replies.innerHTML=`<label class="njNameField">学习署名 <input maxlength="24" value="${escape(state.name)}" aria-label="学习署名"></label><button data-save-name>保存署名</button>`;replies.querySelector('[data-save-name]').onclick=()=>{state.name=replies.querySelector('input').value.trim()||'体验同学';intro.querySelector('input').value=state.name;save();replies.innerHTML='';roleLayer.querySelector('.njDialogueText').textContent='署名已保存：'+state.name+'。继续点击人物完成体验吧。';};};roleLayer.querySelector('.njRoleHeader').insertBefore(nameButton,roleLayer.querySelector('[data-r=motion]'));
 updateRoleProgress();
}
function hasRole(id){return !!state.participation?.[id]&&(!historyLearningTasks[id]||state.participation[id].taskVersion===1&&(state.participation[id].revision||1)===(historyLearningTasks[id].revision||1))&&(state.roleLog||[]).some(r=>r.id===id);}
function updateRoleProgress(){const ids=roleStage==='entrance'?['orderly','reporter']:['radio','citizen'];roleLayer.querySelector('.njProgress').textContent=`学习任务 ${ids.filter(hasRole).length} / 2 · 点击人物查看材料并作答`;roleLayer.querySelectorAll('[data-person]').forEach(b=>b.classList.toggle('visited',hasRole(b.dataset.person)));}
const roleTalks={
 orderly:{name:'会场工作人员',title:'今天的受降仪式与哪一天对应？',text:'今天是1945年9月9日。这里是南京原中央军校大礼堂，将举行中国战区受降仪式。入场时，请留意受降席与日方代表席。',choices:['记下：9月9日、南京、中国战区受降。','这就是9月2日东京湾的签字现场吗？'],correct:0,feedback:['这三项信息相互对应。请带着它们进入会场。','两个现场需要区分：9月2日在东京湾，9月9日在南京。请重新确认入场记录。']},
 reporter:{name:'随行记者',title:'怎样留下可信的历史记录？',text:'作为随行观察员，你要记录时间、地点、人物与事件。画面能帮助我们想象现场；确定事实还要核对档案与文字史料。',choices:['记录并核对史料，区分事实与情境重构。','把画面里的每处细节都当成史实。'],correct:0,feedback:['观察任务已领取：比较三个关键日期，辨别史实与评价。','情境图片不是原始史料，不能仅凭图片认定人物、座次等细节。请再选一次。']},
 radio:{name:'街头广播',title:'受降签字的消息传来',text:'根据南京市地方志相关记载，受降仪式结束后，广播向公众宣告中国战区日军投降签字在南京完成。此处文字是史实概述，不是历史录音。',choices:['记录消息：南京中国战区受降仪式完成。','把这条消息记成8月15日的宣布投降。'],correct:0,feedback:['广播线索已记录：宣布投降、东京湾签字、南京受降，三个时刻不能混同。','8月15日对应日本宣布无条件投降；这里对应南京9月9日的受降仪式。']},
 citizen:{name:'庆祝的市民',title:'战争结束，我们盼望怎样的生活？',text:'终于盼到胜利了。我们盼望家人团聚、孩子安心读书，盼望和平长久。想一想：下面哪句是在评价这场胜利的意义？',choices:['“胜利为人们重建和平生活带来希望。”','“受降仪式在1945年9月9日举行。”'],correct:0,feedback:['你选择的是对胜利作用与意义的评价。请把它与具体的时间、地点等史实区分。','这句话叙述具体史实。请再找一找，对胜利的作用与意义作出判断的是哪句。']}
};
function roleTalk(id){const d=roleTalks[id];roleLayer.querySelector('.njSpeaker b').textContent=d.name;roleLayer.querySelector('.njDialogue h2').textContent=d.title;roleLayer.querySelector('.njDialogueText').textContent=d.text;const replies=roleLayer.querySelector('.njReplies');replies.innerHTML=d.choices.map((text,i)=>`<button data-reply="${i}"><b>${'AB'[i]}</b>${text}</button>`).join('');replies.querySelectorAll('button').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.reply);roleLayer.querySelector('.njDialogueText').textContent=d.feedback[n];b.classList.add(n===d.correct?'correct':'wrong');if(n===d.correct){logRole(id,d.name,d.choices[n]);replies.querySelectorAll('button').forEach(x=>x.disabled=true);updateRoleProgress();}});}
function showEntrance(){roleShell('entrance');}
function showCelebration(){roleShell('celebration');}
