const panoMotionUniforms={njTime:{value:0},njAmbientOn:{value:0}};
let njAmbientLast=0,njAmbientFrames=0;
const njAmbientGLSL=`
uniform float njTime;
uniform float njAmbientOn;
float njHalo(vec2 q,vec2 c,vec2 r){return exp(-dot((q-c)/r,(q-c)/r)*2.0);}
vec3 njAmbient(vec2 uv,vec3 base){
 if(njAmbientOn<0.5)return base;
 vec2 q=vec2(fract(uv.x),1.0-uv.y);
 float t=njTime;
 float lamps=njHalo(q,vec2(.185,.255),vec2(.027,.06))
  +njHalo(q,vec2(.500,.130),vec2(.035,.085))
  +njHalo(q,vec2(.800,.255),vec2(.026,.06));
 float glow=lamps*(.007+.003*sin(t*.72));
 float windows=njHalo(q,vec2(.720,.490),vec2(.12,.20))
  +njHalo(q,vec2(.895,.535),vec2(.080,.21));
 float sunlight=windows*(.004+.003*sin(t*.24+.5));
 vec3 light=vec3(1.0,.78,.43)*(glow+sunlight);
 float dust=0.;
 for(int i=0;i<26;i++){
  float n=float(i);
  float seed=fract(sin(n*87.31+4.1)*513.7);
  float side=mod(n,2.0);
  float cx=mix(.04,.67,side)+seed*mix(.28,.27,side);
  float cy=.34+fract(seed*3.71+t*(.004+seed*.003))*.40;
  cx+=sin(t*.21+n*2.3)*.004;
  vec2 d=(q-vec2(cx,cy))*vec2(2.,1.);
  float size=.0007+seed*.00065;
  float dotLight=exp(-dot(d,d)/(size*size));
  dust+=dotLight*(.027+.018*sin(n+t*.47));
 }
 // Only additive, low-amplitude illumination; original silhouettes and edges stay fixed.
 return base+njAmbientOn*(light+vec3(1.,.88,.65)*dust);
}
`;
window.njInstallPanoMotion=material=>{
 material.onBeforeCompile=shader=>{
  Object.assign(shader.uniforms,panoMotionUniforms);
  shader.fragmentShader=njAmbientGLSL+'\n'+shader.fragmentShader;
  shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',
   '#include <map_fragment>\n#ifdef USE_MAP\ndiffuseColor.rgb=njAmbient(vMapUv,diffuseColor.rgb);\n#endif');
 };
 material.customProgramCacheKey=()=> 'njAmbientNoWarpV1';return material;
};
window.njUpdatePanoMotion=now=>{
 const delta=njAmbientLast?Math.min((now-njAmbientLast)/1000,.2):0;njAmbientLast=now;
 const on=roleMotion&&film.hidden&&!m.classList.contains('njMotionOff')&&!document.hidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
 panoMotionUniforms.njAmbientOn.value=on?1:0;
 if(on){panoMotionUniforms.njTime.value+=delta;njAmbientFrames++;}
};
