const extraVideos={};let extraPlayToken=0;
function stopExtras(){extraPlayToken++;Object.values(extraVideos).forEach(v=>v.pause());}
function syncExtras(){
 const key=roleStage,v=extraVideos[key],skipped=sceneClipMode(v,key);const playing=!!(!skipped&&v&&m.open&&!roleLayer.hidden&&panel.hidden&&roleMotion&&!document.hidden);
 Object.entries(extraVideos).forEach(([k,x])=>{if(k!==key||!playing)x.pause();});
 if(!v)return;
 const b=roleLayer.querySelector('[data-r=motion]');if(b){b.textContent=roleMotion?'暂停视频':'播放视频';b.setAttribute('aria-pressed',String(roleMotion));}
 if(playing&&v.paused){const token=++extraPlayToken;v.play().then(()=>{if(token!==extraPlayToken||roleStage!==key||!m.open||roleLayer.hidden||!roleMotion||document.hidden||!panel.hidden)v.pause();}).catch(e=>{if(e.name!=='AbortError')notify('点击“播放视频”即可继续；人物交流仍可使用。');});}
}
const previousProgress=updateRoleProgress;
updateRoleProgress=function(){if(!extraIds[roleStage])return previousProgress();const ids=extraIds[roleStage];roleLayer.querySelector('.njProgress').textContent=`学习任务 ${ids.filter(hasRole).length} / ${ids.length} · 阅读材料并完成判断`;roleLayer.querySelectorAll('[data-person]').forEach(b=>b.classList.toggle('visited',hasRole(b.dataset.person)));};
const previousMountPeople=mountPeople;mountPeople=function(){if(extraScenes[roleStage])return;previousMountPeople();};
function openSixScene(key){stopExtras();if(key==='hall')enterHall();else roleShell(key);}
function paintSixRoute(){const nav=roleLayer.querySelector('.njRoute');nav.innerHTML=routeScenes.map(([k,t])=>`<button data-six-scene="${k}" class="${k===roleStage?'active':''}">${t}</button>`).join('')+'<button data-six-scene="quiz">07 连线与作业</button>';nav.querySelectorAll('button').forEach(b=>b.onclick=()=>b.dataset.sixScene==='quiz'?timeline():openSixScene(b.dataset.sixScene));}
const sixPreviousShell=roleShell;
roleShell=function(stage){
 stopExtras();const extra=extraScenes[stage];sixPreviousShell(extra?'entrance':stage);
 if(extra){
  roleStage=stage;state.roleStage=stage;save();njSyncEntranceVideo();njSyncCelebrationVideo();
  const c=extraCopy[stage],holder=roleLayer.querySelector('.njRoleArt');holder.replaceChildren();holder.style.backgroundImage=`url("${extra.poster}")`;
  if(!extraVideos[stage]){const v=document.createElement('video');v.className='njExtraVideo';v.dataset.extraScene=stage;v.muted=true;v.defaultMuted=true;v.loop=true;v.playsInline=true;v.preload='none';v.poster=extra.poster;v.src=extra.video;v.setAttribute('aria-label',routeScenes.find(x=>x[0]===stage)[1]+'动态场景');v.addEventListener('error',()=>notify('视频暂未加载，仍可查看场景图片与交流。'));extraVideos[stage]=v;}
  const v=extraVideos[stage];holder.append(v);v.currentTime=0;
  const targets=roleLayer.querySelector('.njRoleTargets');targets.innerHTML=c.targets.map(([id,name,tip,x,y])=>`<button data-person="${id}" style="left:${x}%;top:${y}%">＋ ${name}<span>${tip}</span></button>`).join('');targets.querySelectorAll('button').forEach(b=>b.onclick=()=>roleTalk(b.dataset.person));
  roleLayer.querySelector('.njSpeaker small').textContent='互动情境';roleLayer.querySelector('.njRoleCredit').textContent='AI情境重构 · '+c.credit;labelScene(c.label);
  roleLayer.querySelector('[data-r=motion]').onclick=()=>{togglePeople();syncExtras();};roleLayer.querySelector('[data-r=replayVideo]').onclick=()=>{setSceneClipSkip(stage,false);v.currentTime=0;if(!roleMotion)togglePeople();syncExtras();};
  const next=roleLayer.querySelector('[data-r=continue]');next.textContent=c.next;next.onclick=()=>{if(!extraIds[stage].every(hasRole)){roleLayer.querySelector('.njDialogueText').textContent='请先点击两处热点完成交流，再继续下一段体验。';return;}state[stage+'Done']=true;save();if(stage==='passage')openSixScene('hall');else if(stage==='reporterDesk')openSixScene('celebration');else{leaveRole();timeline();}};
  roleTalk(extraIds[stage][0]);updateRoleProgress();
 }else{
  const next=roleLayer.querySelector('[data-r=continue]');next.textContent=stage==='entrance'?'前往入场通道 →':'走进家书与和平 →';next.onclick=()=>{const ids=stage==='entrance'?['orderly','reporter']:['radio','citizen'];if(!ids.every(hasRole)){roleLayer.querySelector('.njDialogueText').textContent='请先完成两处热点交流，再继续下一段。';return;}state[stage==='entrance'?'entranceDone':'celebrationDone']=true;save();openSixScene(stage==='entrance'?'passage':'family');};
 }
 paintSixRoute();syncExtras();
};
const sixPreviousLeave=leaveRole;leaveRole=function(){stopExtras();sixPreviousLeave();};
const sixPreviousToggle=togglePeople;togglePeople=function(){sixPreviousToggle();syncExtras();};
timeline=function(){stopFilm();stopTravel();allQuiet();leaveRole();baseTimeline();labelScene('胜利档案 · 日期—地点—事件\n（综合练习）');};

const sixPreviousResults=results;results=function(){return {...sixPreviousResults(),extendedScenes:{passage:!!state.passageDone,reporterDesk:!!state.reporterDeskDone,family:!!state.familyDone}};};
const sixPreviousReport=report;report=function(){sixPreviousReport();const badge=panel.querySelector('.njRoleReport');if(badge)badge.textContent=`角色体验：${(state.roleLog||[]).length}/10 项交流记录 · 新增场景完成 ${['passageDone','reporterDeskDone','familyDone'].filter(k=>state[k]).length}/3`;};
const sixPreviousEntry=window.openNanjingImmersive;window.openNanjingImmersive=()=>{const selected=state.roleStage;sixPreviousEntry();if(extraScenes[selected]&&!state.completed)openSixScene(selected);};launch.onclick=window.openNanjingImmersive;
new MutationObserver(syncExtras).observe(m,{attributes:true,attributeFilter:['open','class']});new MutationObserver(syncExtras).observe(roleLayer,{attributes:true,attributeFilter:['hidden']});new MutationObserver(syncExtras).observe(panel,{attributes:true,attributeFilter:['hidden']});
m.addEventListener('close',stopExtras);document.addEventListener('visibilitychange',syncExtras);
const sixPreviousBack=back.onclick;back.onclick=()=>{stopExtras();njUserEntranceVideo.pause();njUserCelebrationVideo.pause();sixPreviousBack();};
window.nanjingSixSceneInfo=()=>({stage:roleStage,route:routeScenes.map(x=>x[0]),label:sceneLabel.textContent,progress:Object.fromEntries(Object.keys(extraIds).map(k=>[k,!!state[k+'Done']])),videos:Object.fromEntries(Object.entries(extraVideos).map(([k,v])=>[k,{ready:v.readyState,time:v.currentTime,duration:v.duration,playing:!v.paused,muted:v.muted,loop:v.loop,error:v.error?.code||null}]))});
window.nanjingOpenSixScene=key=>{if(!routeScenes.some(x=>x[0]===key))return;if(!m.open)window.openNanjingImmersive();openSixScene(key);};

