function learningTalk(id){
 const d=historyLearningTasks[id],dialog=roleLayer.querySelector('.njDialogue'),text=dialog.querySelector('.njDialogueText'),replies=dialog.querySelector('.njReplies');
 roleLayer.dataset.speaker=id;dialog.dataset.talk=id;
 dialog.querySelector('.njSpeaker b').textContent=d.name;
 dialog.querySelector('.njSpeaker span').textContent='历史学习任务 · 对话为教学设计';
 dialog.querySelector('.njSpeaker small').textContent=d.goal;
 dialog.querySelector('h2').textContent=d.title;
 dialog.querySelector('.njActionProp')?.remove();dialog.querySelector('.njHistoryTask')?.remove();dialog.querySelector('.njTaskOutcome')?.remove();
 text.textContent=d.material;
 const area=document.createElement('div');area.className='njHistoryTask';
 area.innerHTML='<small class="njTaskStep"></small><b class="njTaskQuestion"></b>';
 replies.before(area);replies.classList.add('njActionReplies');replies.dataset.historyOptions='';
 const outcome=document.createElement('div');outcome.className='njTaskOutcome';
 outcome.innerHTML='<p class="njTaskFeedback" role="status"></p><div class="njTaskCompletion" role="status"></div><small class="njTaskSource">史实依据：<a target="_blank" rel="noopener">'+(d.source.includes('saac.gov.cn')?'国家档案局':'南京市地方志工作办公室')+'</a> · 摘记与题目为教学编写</small>';
 outcome.querySelector('a').href=d.source;replies.after(outcome);
 const feedback=outcome.querySelector('.njTaskFeedback'),completion=outcome.querySelector('.njTaskCompletion');
 const passed=hasRole(id);
 let index=0;
 function revealOutcome(){requestAnimationFrame(()=>{const target=completion.firstElementChild||feedback;target.scrollIntoView({block:'nearest'});});}
 function markSaved(label){const saved=document.createElement('span');saved.className='njActionSaved';saved.textContent=label;completion.replaceChildren(saved);}
 function paint(){
  const q=d.questions[index];area.querySelector('.njTaskStep').textContent='问题 '+(index+1)+' / '+d.questions.length;
  area.querySelector('.njTaskQuestion').textContent=q.question;feedback.textContent='';completion.replaceChildren();
  const body=dialog.querySelector('.njDialogueContent');if(body)body.scrollTop=0;
  replies.innerHTML=q.options.map((label,i)=>`<button data-history-answer="${i}" aria-label="${'ABC'[i]} ${escape(label)}"><b class="njAnswerLetter" aria-hidden="true">${'ABC'[i]}</b><span class="njAnswerText">${escape(label)}</span><span class="njAnswerMark" aria-hidden="true"></span></button>`).join('');
  replies.querySelectorAll('button').forEach(b=>b.onclick=()=>{
   if(id==='evidence'&&(!state.propActivity?.completed||!state.propActivity.record||!state.evidenceRead)){
    feedback.textContent=!state.propActivity?.completed||!state.propActivity.record?'先把大厅观察记录带回来，再结合档案校稿。':'先打开档案核验签署与呈递，再用材料支持你的修改。';revealOutcome();return;
   }
   const n=Number(b.dataset.historyAnswer),ok=n===q.correct;
   attempt('historyTask:'+id,{task:d.title,question:q.question,answer:q.options[n]},ok);
   b.classList.add(ok?'correct':'wrong');b.setAttribute('aria-pressed','true');b.querySelector('.njAnswerMark').textContent=ok?'✓':'×';
   feedback.textContent=(ok?'判断正确。':'再想一想。')+q.why;
   if(!ok){b.disabled=true;syncSceneInteractionControls();revealOutcome();return;}
   replies.querySelectorAll('button').forEach(x=>x.disabled=true);
   if(index+1<d.questions.length){const next=document.createElement('button');next.className='njNextTaskQuestion';next.textContent='继续核对下一问 →';next.onclick=()=>{index++;paint();};completion.append(next);}
   else{
    const label=d.questions.map(x=>x.options[x.correct]).join('；');
    state.participation[id]={taskVersion:1,revision:d.revision||1,label,questions:d.questions.length,at:new Date().toISOString()};
     if(id==='evidence')state.reportCorrection={revision:1,at:new Date().toISOString(),original:'冈村宁次签署降书后，亲自将降书递交给何应钦。',corrected:q.options[n],fieldRecord:JSON.parse(JSON.stringify(state.propActivity.record)),source:state.evidenceRead.source};
    const prior=(state.roleLog||[]).find(x=>x.id===id);if(prior){prior.label=d.title;prior.choice=label;}else logRole(id,d.title,label);
    save();updateRoleProgress();markSaved('✓ 本任务已完成，结论已记入手册');
   }
   syncSceneInteractionControls();revealOutcome();
  });
  syncSceneInteractionControls();
 }
 if(passed){
  area.querySelector('.njTaskStep').textContent='任务已完成';area.querySelector('.njTaskQuestion').textContent=d.goal;
  replies.replaceChildren();feedback.textContent=d.questions.map(q=>q.why).join(' ');markSaved('✓ 已完成 '+d.questions.length+' 项历史判断');
 }else paint();
 syncSceneInteractionControls();
}
state.participation=state.participation||{};
roleTalk=function(id){
 if(historyLearningTasks[id])return learningTalk(id);
 const d=actionStories[id];if(!d)return;
 roleLayer.dataset.speaker=id;
 const title=roleLayer.querySelector('.njDialogue h2'),text=roleLayer.querySelector('.njDialogueText'),replies=roleLayer.querySelector('.njReplies');
 roleLayer.querySelector('.njSpeaker b').textContent=d.name;title.textContent=d.title;text.textContent=d.text;
 roleLayer.querySelector('.njActionProp')?.remove();
 const prop=document.createElement('div');prop.className='njActionProp';prop.setAttribute('aria-live','polite');replies.before(prop);
 const done=[];let step=0;replies.classList.add('njActionReplies');
 function drawProp(){
  if(id==='evidence'){prop.innerHTML=['日期','地点','事件'].map((label,i)=>`<span class="${done.length>i?'filled':''}"><small>${label}</small><b>${done.length>i?['1945年9月9日','南京','中国战区受降'][i]:'待记录'}</b></span>`).join('');}
  else if(id==='letterPeace'){prop.innerHTML=`<span class="njEnvelope ${done.length===2?'sealed':''}"><b>${done.length===0?'一封待寄的家书':done.length===1?'家书已折好':'✉ 平安 · 已封好'}</b></span>`;}
  else if(done.length){prop.innerHTML=done.map(label=>`<span class="filled"><b>✓ ${escape(label)}</b></span>`).join('');}
 }drawProp();
 function finish(label){state.participation[id]={label,at:new Date().toISOString()};logRole(id,d.name,label);save();updateRoleProgress();replies.innerHTML='<span class="njActionSaved">✓ 已放入我的手册</span>';}
 function paint(){
  const list=d.pick||[d.steps[step]];
  replies.innerHTML=list.map(([label],i)=>`<button data-action-choice="${i}">${escape(label)} <span aria-hidden="true">→</span></button>`).join('');
  replies.querySelectorAll('button').forEach(b=>b.onclick=()=>{
   const item=d.pick?d.pick[Number(b.dataset.actionChoice)]:d.steps[step];text.textContent=item[1];done.push(item[0]);drawProp();
   if(d.pick||++step===d.steps.length)finish(item[0]);else paint();
  });
 }paint();
};
const actionShell=roleShell;roleShell=function(stage){actionShell(stage);
 roleLayer.querySelectorAll('[data-person]').forEach(b=>{const t=b.querySelector('span');if(t)t.textContent=({orderly:'核对日期与事件',reporter:'核实历史证据',usherTask:'领取观察清单',observation:'留下待查问题',evidence:'校正待发稿',headline:'辨别史实与评价',radio:'打开收音机',citizen:'加入这一刻',letterPeace:'一起封好家书',schoolHope:'留下书签寄语'})[b.dataset.person]||t.textContent;});
 if(!extraScenes[stage])roleTalk(stage==='entrance'?'orderly':'radio');
};
const actionResults=results;results=function(){return {...actionResults(),participation:state.participation||{}};};
const actionRestart=restartDemo;restartDemo=function(){actionRestart();state.participation={};save();};
lecture.querySelector('[data-l=restart]').onclick=restartDemo;

