const film=document.createElement('section');film.id='njNarrative';film.hidden=true;m.append(film);
const travel=document.createElement('section');travel.id='njTravel';travel.hidden=true;m.append(travel);
let filmIndex=0,filmToken=0,travelTimer=0,travelToken=0,insideTravel=false;
state.storyWatched=state.storyWatched||[];state.branches=state.branches||[];state.videoProgress=state.videoProgress||{};
// Foreground playback is the only owner of narrative media.
function stopFilm(){const v=film.querySelector('video');if(v){v.pause();v.onpause?.();}film._sizeObserver?.disconnect();film._sizeObserver=null;if(document.fullscreenElement===film)document.exitFullscreen?.().catch(()=>{});filmToken++;film.hidden=true;}
function stopTravel(){clearTimeout(travelTimer);travelToken++;travel.hidden=true;if(travel._njArrivalHandler){travel.removeEventListener('nj-map-arrived',travel._njArrivalHandler);travel._njArrivalHandler=null;}}
function allQuiet(){stopExtras();stopVoice();roleLayer.querySelectorAll('video').forEach(v=>v.pause());}
function finishShot(id){state.storyWatched=state.storyWatched||[];if(!state.storyWatched.includes(id))state.storyWatched.push(id);save();}
function povWatched(role){return (state.storyWatched||[]).includes(povClips[role]?.id);}
function povStatus(role){return roleFinished(role)?'✓ 本视角已完成':povWatched(role)?'已观看 · 任务待完成':shotHandled(role)?'已跳过 · 任务待完成':'待观看 · 任务待完成';}
function mergePlayed(ranges){const merged=[];for(const r of ranges.filter(r=>Number.isFinite(r[0])&&Number.isFinite(r[1])&&r[1]>r[0]).sort((a,b)=>a[0]-b[0])){const last=merged.at(-1);if(last&&r[0]<=last[1]+.03)last[1]=Math.max(last[1],r[1]);else merged.push([...r]);}return merged;}
function playShot(index=0,fromStart=false){
 const shot=storyShots[index];if(!shot||['celebration','family'].includes(shot.stage))return;
 const owner=shot.role||({guide:'audience',closeup:'japanese',closure:'civilian'})[shot.id];
 if(owner&&owner!==state.activePerspective){notify('请先选择对应身份，再观看这个片段。');return;}
 stopFilm();stopTravel();hide();allQuiet();pause();
 if(shot.stage==='hall'){leaveRole();roleStage='hall';state.roleStage='hall';}
 filmIndex=index;film.hidden=false;const token=++filmToken;
 state.videoProgress=state.videoProgress||{};const prior=state.videoProgress[shot.id]||{};
 let ranges=prior.ranges||[],lastSave=0,failed=false;
 film.innerHTML=`<header><button data-film="exit">← ${shot.stage==='hall'&&owner!=='audience'?'选择视角':'返回'+routeNames[shot.stage]}</button><div><b>${shot.title}</b><small>${shot.view}</small></div><button data-film="pause">暂停</button><button data-film="replay">重播</button><button data-film="skip">跳过视频 →</button><button data-film="fullscreen">全屏</button><button data-film="roles">选择视角</button></header><div class="povVideoStage"><video playsinline muted preload="metadata" poster="${shot.media.poster}" aria-label="${shot.title}"></video><button class="njFilmStart" data-film="start" hidden>点击播放</button></div><div class="povFilmNotes"><p class="njFilmCaption" role="status">${shot.caption}</p><footer hidden><div class="filmNextCopy"><span>接下来</span><p>${shot.reflection}</p></div><div class="filmNextActions"><button data-film="next">${shot.nextLabel}</button>${index===0?'<button data-film="detail">选看签字特写</button>':''}</div></footer><small class="njFilmCredit">AI教学情境重构 · 非历史原始影像 · 静音播放</small></div>`;
 const v=film.querySelector('video'),footer=film.querySelector('footer'),start=film.querySelector('[data-film=start]'),pauseButton=film.querySelector('[data-film=pause]');film.querySelector('[data-film=roles]').hidden=state.journeyMode==='main'&&!mainCanChangeView();
 v.muted=true;v.defaultMuted=true;v.loop=false;v.src=shot.media.video;
 const stage=film.querySelector('.povVideoStage');stage.style.setProperty('--pov-poster','url("'+shot.media.poster+'")');
 const fit=()=>{const r=stage.getBoundingClientRect(),ratio=v.videoWidth&&v.videoHeight?v.videoWidth/v.videoHeight:16/9;stage.toggleAttribute('data-narrow-gutter',(r.width-Math.min(r.width,r.height*ratio))/2<95);};
 const sizeObserver=new ResizeObserver(fit);film._sizeObserver=sizeObserver;sizeObserver.observe(stage);fit();v.addEventListener('loadedmetadata',fit);
 v.addEventListener('emptied',()=>sizeObserver.disconnect(),{once:true});
 film.querySelector('[data-film=fullscreen]').onclick=()=>{if(document.fullscreenElement===film)document.exitFullscreen?.().catch(()=>{});else film.requestFullscreen?.().catch(()=>notify('当前浏览器暂不支持全屏，仍可继续观看。'));};

 function persist(){if(token!==filmToken)return;const played=[];for(let i=0;i<v.played.length;i++)played.push([v.played.start(i),v.played.end(i)]);ranges=mergePlayed([...ranges,...played]);state.videoProgress[shot.id]={ranges,time:v.currentTime,duration:Number.isFinite(v.duration)?v.duration:0};save();}
 function begin(){if(token!==filmToken)return;v.play().catch(()=>{if(token!==filmToken)return;start.hidden=false;pauseButton.textContent='播放';});}
 v.onloadedmetadata=()=>{if(!fromStart&&prior.time>0&&prior.time<v.duration-.35)v.currentTime=prior.time;};
 v.ontimeupdate=()=>{if(performance.now()-lastSave>1000){persist();lastSave=performance.now();}};
 v.onpause=()=>{persist();pauseButton.textContent=v.ended?'已播完':'继续播放';};
 v.onplay=()=>{if(token!==filmToken){v.pause();return;}start.hidden=true;footer.hidden=true;film.querySelector('.njFilmCaption').textContent=shot.caption;allQuiet();pauseButton.textContent='暂停';};
 v.onended=()=>{if(token!==filmToken||failed)return;persist();const covered=mergePlayed(ranges.map(([a,b])=>[Math.max(0,a),Math.min(v.duration,b)])).reduce((n,r)=>n+r[1]-r[0],0);if(v.duration>0&&covered/v.duration>=.9){finishShot(shot.id);footer.hidden=false;film.querySelector('.njFilmCaption').textContent=state.journeyMode==='main'?'片段已观看，继续完成当前场景的观察与互动。':'已观看。完成对应互动后才记录本视角完成。';}else{film.querySelector('.njFilmCaption').textContent='尚未看完主要内容，请重播补看；当前未计为已观看。';start.hidden=false;start.textContent='重新完整观看';}pauseButton.textContent='已播完';};
 v.onerror=()=>{if(token!==filmToken)return;failed=true;footer.hidden=true;film.querySelector('.njFilmCaption').textContent='片段加载失败，已保留封面。请重播重试，或返回场景；不会计为已观看。';pauseButton.textContent='未能播放';start.hidden=true;};
 start.onclick=()=>{if(v.ended)v.currentTime=0;begin();};
 pauseButton.onclick=()=>{if(v.paused){if(v.ended)v.currentTime=0;begin();}else v.pause();};
 film.querySelector('[data-film=skip]').onclick=()=>skipCurrentShot(index);
 film.querySelector('[data-film=replay]').onclick=()=>playShot(index,true);
 film.querySelector('[data-film=roles]').onclick=fiveHub;
 film.querySelector('[data-film=exit]').onclick=()=>{stopFilm();if(shot.stage==='hall'&&owner!=='audience')fiveHub();else resumeScene();};
 film.querySelector('[data-film=detail]')?.addEventListener('click',()=>playShot(4));
 film.querySelector('[data-film=next]').onclick=()=>{if(!(state.storyWatched||[]).includes(shot.id))return;stopFilm();if(owner==='chinese'||(owner==='japanese'&&[0,4].includes(index))){showRoleCheck(owner);return;}if(index===2){openSixScene('passage');return;}resumeScene();if(index===3)roleTalk('evidence');if(index===5)roleTalk('letterPeace');if(index===7)roleTalk('radio');};
 begin();
}

