const routeXY=[[100,155],[275,105],[445,155],[615,105],[785,155],[960,105]];
function travelTo(from,to,go){
 stopTravel();allQuiet();const token=travelToken;travel.hidden=false;
 const keys=Object.keys(routeNames),a=Math.max(0,keys.indexOf(from)),b=keys.indexOf(to),pts=routeXY;
 const d=`M ${pts[a][0]},${pts[a][1]} Q ${(pts[a][0]+pts[b][0])/2},10 ${pts[b][0]},${pts[b][1]}`;
 travel.innerHTML=`<p class="njTravelYear">1945 · 南京</p><h2>${routeNames[from]||'历史现场'} <span>→</span> ${routeNames[to]}</h2><svg viewBox="0 0 1060 240" role="img" aria-label="南京课堂场景路线示意"><path class="njRoad" d="M100 155 L275 105 L445 155 L615 105 L785 155 L960 105"/>${keys.map((k,i)=>`<g class="${k===to?'destination':''}"><circle cx="${pts[i][0]}" cy="${pts[i][1]}" r="8"/><text x="${pts[i][0]}" y="${pts[i][1]+35}" text-anchor="middle">${routeNames[k]}</text></g>`).join('')}<path id="njTravelPath" class="njTravelPath" d="${d}"/><circle class="njTravelDot" r="6"><animateMotion dur="1.35s" fill="freeze" path="${d}"/></circle></svg><article><small>下一幕</small><h3>${routeNames[to]}</h3><p>${({hall:'进入会场，从两个代表席观察正式受降。',reporterDesk:'把刚才看到的线索，整理成自己的记录。',celebration:'从会场走到街头，看看消息怎样传向人群。',family:'从历史的大事，走进一个家庭对和平的盼望。',passage:'带着观察任务，沿通道进入会场。',entrance:'重新从会场外开始这次体验。'})[to]}</p></article><small>教学路线示意 · 不表示实测地理距离</small><button data-travel-skip>直接到达 →</button>`;
 const arrive=()=>{if(token!==travelToken)return;stopTravel();insideTravel=true;try{go();}finally{insideTravel=false;}};
 travel.querySelector('button').onclick=arrive;travelTimer=setTimeout(arrive,1550);
}
const narrativeOpen=openSixScene;
