function checklist(){
 stopFilm();stopTravel();allQuiet();
 const groups=[['entrance',['orderly','reporter']],['passage',['usherTask','observation']],['hall',[]],['reporterDesk',['evidence','headline']]];
 const poster=k=>k==='hall'?chapterMedia.reception.poster:k==='entrance'?roleArt.entrance:k==='celebration'?roleArt.celebration:extraScenes[k].poster;
 const supplementary=[2,3,4];const watched=i=>state.storyWatched.includes(storyShots[i].id);const sceneFilm={entrance:2,hall:4,reporterDesk:3,family:5};const done=k=>k==='hall'?state.viewed.length===3:groups.find(x=>x[0]===k)[1].every(hasRole)&&(sceneFilm[k]===undefined||watched(sceneFilm[k]));
 show('我的胜利档案 · 完成与待补',`<p>每张卡都能回到相应场景。完成的经历已经保存，未完成的可以接着做。</p><div class="njReviewGrid">${groups.map(([k,ids],i)=>`<button data-review="${k}" class="${done(k)?'done':''}"><img src="${poster(k)}" alt="${routeNames[k]}"><small>第${i+1}幕</small><b>${routeNames[k]}</b><span>${done(k)?'✓ 已完成':'○ 待补充'}</span><em>${k==='hall'?`研读 ${state.viewed.length}/3`:`互动 ${ids.filter(hasRole).length}/${ids.length}${sceneFilm[k]!==undefined?' · 剧情 '+(watched(sceneFilm[k])?'✓':'○'):''}`}</em></button>`).join('')}</div><div class="njReviewTasks"><button data-review="film">${[0,4].every(watched)?'✓':'○'} 日方签字片段（观看） · ${[0,4].filter(watched).length}/2</button><button data-review="quiz">${state.timeline?'✓':'○'} 日期连线</button><button data-review="quiz">${state.exam?'✓':'○'} 最终判断</button></div><p class="njSupplementLabel">片段观看（不代替任务）· ${supplementary.filter(watched).length}/${supplementary.length}</p><div class="njSupplementGrid">${supplementary.map(i=>`<button data-supplement="${i}"><img src="${storyShots[i].media.poster}" alt=""><b>${storyShots[i].title}</b><span>${watched(i)?"✓ 已观看":"○ 待观看"} · 6秒</span></button>`).join('')}</div><button class="questPrimary" data-review="quiz">继续整理日期与作业 →</button>`);
 panel.querySelectorAll('[data-supplement]').forEach(b=>b.onclick=()=>{hide();const i=Number(b.dataset.supplement);if(storyShots[i].stage!=='hall')roleShell(storyShots[i].stage);playShot(i);});
  panel.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{hide();const k=b.dataset.review;if(k==='quiz')timeline();else if(k==='film')perspectives();else openSixScene(k);});
}
