for(const [label,fn] of [['剧情视角',perspectives],['完成情况',checklist]]){const b=document.createElement('button');b.textContent=label;b.onclick=fn;lecture.querySelector('.lectureHeader nav').append(b);}
const narrativeReport=report;report=function(){stopFilm();stopTravel();allQuiet();narrativeReport();const summary=document.createElement('section');summary.className='povSummary';summary.innerHTML='<h3>四视角实际体验</h3>'+fiveRoles.map(r=>'<p>'+identityNames[r.id]+'：'+povStatus(r.id)+'</p>').join('');panel.querySelector('.questActions').before(summary);const b=document.createElement('button');b.textContent='查看四视角完成情况';b.onclick=checklist;panel.querySelector('.questActions')?.prepend(b);};
