const narrativeBack=back.onclick;back.onclick=()=>{stopFilm();stopTravel();narrativeBack();};
m.addEventListener('close',()=>{stopFilm();stopTravel();});
m.addEventListener('keydown',e=>{if(e.key==='Escape'&&(!film.hidden||!travel.hidden)){e.preventDefault();e.stopImmediatePropagation();stopFilm();stopTravel();resumeScene();}},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden)film.querySelector('video')?.pause();});
window.nanjingOpenStory=playShot;window.nanjingPerspectives=perspectives;window.nanjingChecklist=checklist;
window.nanjingSupplementInfo=()=>storyShots.map((s,i)=>({index:i,id:s.id,title:s.title,stage:s.stage,watched:state.storyWatched.includes(s.id),sound:!!s.sound}));
window.nanjingNarrativeInfo=()=>({film:!film.hidden,index:filmIndex,travel:!travel.hidden,watched:[...state.storyWatched],branches:state.branches.length,duration:film.querySelector('video')?.duration,playing:!!film.querySelector('video')&&!film.querySelector('video').paused,muted:film.querySelector('video')?.muted,ready:film.querySelector('video')?.readyState,error:film.querySelector('video')?.error?.code||null});

// Five explicit identities. Tasks and playback never imply each other's completion.
const fiveRoles=[
 {id:'chinese',name:'中方席位',task:'观看接收降书，判断文件交接方向。',poster:chapterMedia.reception.poster},
 {id:'japanese',name:'日方席位',task:'观看签署与递交，核对双方身份。',poster:chapterMedia.signing.poster},
 {id:'audience',name:'观众',task:'领取入场任务，观看交接，再环视并研读三条资料。',poster:chapterMedia.audience.poster},
 {id:'reporter',name:'记者',task:'观察现场取景与拍摄，整理线索与报道标题。',poster:chapterMedia.camera.poster},
];
state.roleChecks=state.roleChecks||{};state.activePerspective=state.activePerspective||'audience';
function roleFinished(id){
 if(!shotHandled(id))return false;
 if(id==='japanese'||id==='chinese')return !!state.roleChecks?.[id];
 if(id==='reporter')return ['evidence','headline'].every(hasRole);
 if(id==='audience')return ['orderly','reporter','usherTask','observation'].every(hasRole)&&state.viewed.length===3;
 if(id==='civilian')return ['radio','citizen','letterPeace','schoolHope'].every(hasRole)&&(state.storyWatched||[]).includes('closure');
 return false;
}
function fiveHub(){
 stopFilm();stopTravel();allQuiet();
 show('选择你的身份',`<p class="fiveIntro">同一场历史，五种身份。每次只跟随一个人的经历；切换身份时回到这里。</p><div class="fiveGrid">${fiveRoles.map(r=>`<button data-five="${r.id}"><img src="${r.poster}" alt="${r.name}的观察位置"><b>${r.name}</b><p>${r.task}</p><span>${roleFinished(r.id)?'✓ 本身份任务已完成':'进入体验 · 任务待完成'}</span></button>`).join('')}</div><p class="fiveNote">观看片段、完成操作与提交答案分别记录。画面为教学情境重构。</p>`);
 panel.querySelectorAll('[data-five]').forEach(b=>b.onclick=()=>selectRole(b.dataset.five));
}
