checklist=function(){modelCleanup();stopFilm();stopTravel();allQuiet();show('我的主线记录',`<p>观看与操作分别记录；完成本场景的全部要求才显示“已完成”。</p><div class="mainReview">${mainScenes.map((k,i)=>`<button data-main-review="${k}"><img src="${mainPoster(k)}" alt=""><b>${i+1}. ${routeNames[k]}</b><span>${sceneDone(k)?'✓ 已完成':'待完成'} · ${k==='hall'?`研读 ${state.viewed.length}/3`:`互动 ${tasksFor(k).filter(hasRole).length}/${tasksFor(k).length}`}</span></button>`).join('')}</div><div class="mainTools"><button data-resume>继续主线 →</button><button data-identities>五身份入口</button><button data-archive>日期连线与作业</button></div>`);panel.querySelectorAll('[data-main-review]').forEach(b=>b.onclick=()=>{state.journeyMode='main';openSixScene(b.dataset.mainReview);});panel.querySelector('[data-resume]').onclick=mainStart;panel.querySelector('[data-identities]').onclick=fiveHub;panel.querySelector('[data-archive]').onclick=()=>{if(state.viewed.length<3){notify('先读完会场三段资料，再做日期连线。');return;}leaveRole();baseTimeline();};};
