function compactHeader(h){if(!h)return;h.querySelectorAll(':scope>button,:scope>nav>button').forEach(b=>b.hidden=true);h.querySelector('.cleanTop')?.remove();const nav=document.createElement('nav');nav.className='cleanTop';nav.innerHTML='<button data-clean="back">← 返回地图</button><button data-clean="identity">选择视角</button><button data-clean="record">本章学习记录</button><button data-clean="source">史料手册</button><button data-clean="more">更多 ⋯</button>';h.append(nav);nav.querySelector('[data-clean=back]').onclick=()=>back.click();nav.querySelector('[data-clean=identity]').textContent='切换视角';nav.querySelector('[data-clean=identity]').hidden=state.journeyMode==='main'&&!mainCanChangeView();nav.querySelector('[data-clean=identity]').onclick=fiveHub;nav.querySelector('[data-clean=record]').onclick=chapterRecord;nav.querySelector('[data-clean=source]').onclick=notebook;nav.querySelector('[data-clean=more]').onclick=moreMenu;}
