function measureNanjingLayout(){
 njLayoutFrame=0;if(!m.open)return;
 const box=m.getBoundingClientRect(),w=box.width,h=box.height;
 const roleVisible=!roleLayer.hidden,header=roleVisible?roleLayer.querySelector('.njRoleHeader'):lecture.querySelector('.lectureHeader');
 const hb=header?Math.max(48,header.getBoundingClientRect().bottom-box.top):60;
 const set=(k,v)=>{const next=Math.round(v)+'px';if(m.style.getPropertyValue(k)!==next)m.style.setProperty(k,next);};
 set('--nj-header-bottom',hb);set('--nj-dialog-max',Math.max(150,Math.min(h*.47,h-hb-155)));
 const title=sceneLabel.getBoundingClientRect(),route=roleVisible?roleLayer.querySelector('.njRoute'):lecture.querySelector('.njRoute');
 if(route){
  const top=w<1100?title.bottom-box.top+12:Math.max(title.bottom-box.top+18,h*.24);
  set('--nj-route-top',top);
  const rb=route.getBoundingClientRect().bottom-box.top;set('--nj-hotspot-top',rb+16);
  const dialog=roleVisible?roleLayer.querySelector('.njDialogue'):lecture.querySelector('.lectureDialogue'),db=dialog?.getBoundingClientRect().top-box.top||h*.58;
  if(w>=650){
   const controlsBottom=w<1100?rb:Math.max(hb,title.bottom-box.top);
   const targets=roleVisible?[...roleLayer.querySelectorAll('.njRoleTargets button')]:[];
   for(const b of targets){
    if(!b.dataset.njOriginalX){b.dataset.njOriginalX=b.style.left||'50%';b.dataset.njOriginalY=b.style.top||'40%';}
    const r=b.getBoundingClientRect(),desiredX=parseFloat(b.dataset.njOriginalX)*w/100,desiredY=parseFloat(b.dataset.njOriginalY)*h/100;
    const left=w>=1100?210:12;
    const x=Math.max(left+r.width/2,Math.min(w-r.width/2-14,desiredX));
    const low=controlsBottom+r.height/2+14,high=db-r.height/2-14;
    b.style.setProperty('left',Math.round(x)+'px','important');b.style.setProperty('top',Math.round(high>=low?Math.max(low,Math.min(high,desiredY)):Math.max(low,desiredY))+'px','important');
   }
   if(targets.length===2){const [a,b]=targets.map(x=>x.getBoundingClientRect());if(a.left<b.right+10&&a.right+10>b.left&&a.top<b.bottom&&a.bottom>b.top){const gap=12,total=a.width+b.width+gap,start=Math.max(w>=1100?220:14,(w-total)/2);targets[0].style.setProperty('left',(start+a.width/2)+'px','important');targets[1].style.setProperty('left',(start+a.width+gap+b.width/2)+'px','important');}}
  }else{for(const b of roleLayer.querySelectorAll('.njRoleTargets button')){if(!b.dataset.njOriginalX){b.dataset.njOriginalX=b.style.left||'50%';b.dataset.njOriginalY=b.style.top||'40%';}b.style.removeProperty('left');b.style.removeProperty('top');}}
 }
}
