collect=function(i){
 const c=clues[i],keys=[['nanjing_venue'],['tokyo_document','nanjing_document'],['nanjing_signing']][i];
 const observe=[
  '观察旧礼堂及门前场地，再把“南京、9月9日、中国战区受降”对应起来。',
  '左侧是9月2日东京湾签字的投降文书首页；右侧是9月9日南京受降的降书照片。先核对日期和受降范围，再比较文件。',
  '这张档案照片记录了冈村宁次签署降书后盖章。它与课件的AI会场插画属于不同性质的材料；核实人物和动作时，应先查看照片及档案说明。'
 ][i];
 show(c.title,`<p class="njArchiveIntro">${observe}</p><div class="njArchiveGallery ${keys.length===2?'paired':''}">${keys.map(archiveFigure).join('')}</div><p class="questClueText">${c.text}</p><div class="questCoach"><b>研学提示</b><p>${c.tip}</p></div><div class="njArchiveActions"><button class="questPrimary" data-q="collect">${state.clues.includes(i)?'已在手册中 · 返回现场':'收进我的线索手册'} →</button><button data-source-notebook>返回史料手册</button></div><p class="questSource">图片已内嵌，可离线查看。档案图片按原样展示；具体来源见各图说明。</p>`);
 panel.querySelector('article').classList.add('njArchiveCard');bindArchiveZoom(i);
 panel.querySelector('[data-source-notebook]').onclick=notebook;
 panel.querySelector('[data-q=collect]').onclick=()=>{if(!state.clues.includes(i)){state.clues.push(i);save();}hide();renderHud();notify('史料已收进手册 · '+state.clues.length+'/3');};
};

