const chapterTitles={entrance:'史实核验员',passage:'受降观察员',hall:'现场研读者',reporterDesk:'历史记录员'};
let awardRun=state.runId||state.started,awardPending=0,awardTimer=0,awardQueue=[];
const awardToast=document.createElement('aside');awardToast.id='njTitleAward';awardToast.hidden=true;awardToast.setAttribute('role','status');awardToast.setAttribute('aria-live','polite');m.append(awardToast);
function seedChapterAwards(){
 state.chapterAwards=state.chapterAwards||{};
 for(const k of mainScenes)if(sceneDone(k)&&!state.chapterAwards[k])state.chapterAwards[k]={title:chapterTitles[k],at:null};
}
queueMicrotask(seedChapterAwards);
function clearChapterCelebration(){cancelAnimationFrame(njFireworkFrame);njFireworkFrame=0;clearTimeout(awardTimer);awardTimer=0;awardQueue=[];awardToast.hidden=true;awardToast.replaceChildren();}
function playChapterCelebration(){
 if(!awardQueue.length||!m.open)return;
 const k=awardQueue.shift(),title=chapterTitles[k];
 awardToast.innerHTML=`<canvas class="njConfettiCanvas" aria-hidden="true"></canvas><div class="njAwardCard"><span class="njAwardSeal" aria-hidden="true">✦</span><div><small>${routeNames[k]} · 任务完成</small><p>获得「<strong>${title}</strong>」称号</p></div></div>`;
 awardToast.hidden=false;awardToast.classList.remove('celebrate');void awardToast.offsetWidth;awardToast.classList.add('celebrate');
 drawTitleConfetti(awardToast.querySelector('canvas'));
 awardTimer=setTimeout(()=>{awardTimer=0;awardToast.hidden=true;awardToast.replaceChildren();playChapterCelebration();},3200);
}
function checkChapterAchievements(){
 awardPending=0;
 const run=state.runId||state.started;
 if(run!==awardRun){clearChapterCelebration();awardRun=run;state.chapterAwards={};}
 state.chapterAwards=state.chapterAwards||{};
 const earned=mainScenes.filter(k=>sceneDone(k)&&!state.chapterAwards[k]);
 if(!earned.length)return;
 for(const k of earned){state.chapterAwards[k]={title:chapterTitles[k],at:new Date().toISOString()};awardQueue.push(k);}
 save();if(!awardTimer)playChapterCelebration();
 // Award feedback never changes the scene; the learner continues to the record receipt.
}
document.addEventListener('njChapterProgressSaved',()=>{if(!awardPending)awardPending=setTimeout(checkChapterAchievements,0);});
m.addEventListener('close',clearChapterCelebration);
