let njFireworkFrame=0;
function drawTitleConfetti(canvas){
 cancelAnimationFrame(njFireworkFrame);njFireworkFrame=0;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,1.5),ctx=canvas.getContext('2d');
 canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);
 const colors=['#e7bc68','#8bbba7','#df9ca6','#91b8d0','#d8c49a'];
 // One small handful of paper from either side, with no light trails or glow.
 const pieces=Array.from({length:28},(_,i)=>({
  x:w*.5+(i%2?-1:1)*Math.min(225,w*.36),y:48+(i%4)*5,
  vx:(i%2?-1:1)*(24+(i%7)*9),vy:-36-(i%5)*12,
  angle:i*1.7,spin:(i%2?1:-1)*(2+i%3),color:colors[i%colors.length],size:4+i%3
 }));let start=null,last=0;
 function frame(time){
  if(start===null)start=time;const elapsed=time-start,t=elapsed/1000;
  if(elapsed>2400||awardToast.hidden){ctx.clearRect(0,0,w,h);njFireworkFrame=0;return;}
  if(time-last>=30){last=time;ctx.clearRect(0,0,w,h);
   ctx.globalAlpha=.85*Math.min(1,elapsed/120)*Math.min(1,(2400-elapsed)/700);
   for(const p of pieces){
    const x=p.x+p.vx*(1-Math.exp(-1.5*t))/1.5+Math.sin(t*3+p.angle)*5;
    const y=p.y+p.vy*t+40*t*t;
    ctx.save();ctx.translate(x,y);ctx.rotate(p.angle+p.spin*t);
    ctx.scale(1,.45+.55*Math.abs(Math.cos(t*4+p.angle)));
    ctx.fillStyle=p.color;ctx.fillRect(-p.size/2,-p.size/3,p.size,p.size*.66);ctx.restore();
   }ctx.globalAlpha=1;
  }
  njFireworkFrame=requestAnimationFrame(frame);
 }
 njFireworkFrame=requestAnimationFrame(frame);
}

