 panel.querySelector('article').classList.add('njNewsReport');
 const persist=()=>{const submitted=state.newsReport?.submitted||null;state.newsReport={...state.newsReport,...Object.fromEntries([...panel.querySelectorAll('[data-news]')].map(e=>[e.dataset.news,e.value])),submitted};save();};
 panel.querySelectorAll('[data-news]').forEach(e=>e.oninput=()=>{state.newsReport={...state.newsReport,submitted:null,acknowledgedAt:null};persist();});
 panel.querySelector('[data-news-source]').onclick=()=>{persist();evidenceObservation();panel.querySelector('[data-evidence-return]').textContent='返回我的报道 →';panel.querySelector('[data-evidence-return]').onclick=writeNewsReport;};
 panel.querySelector('[data-news-scene]').onclick=()=>{persist();hide();};
