function readableAttempt(a){
 if(a.kind.startsWith('historyTask:'))return {kind:'剧情判断',text:(a.answer?.question||'')+' → '+(a.answer?.answer||'')};
 if(a.kind==='matching')return {kind:'日期连线',text:(a.answer||[]).map(x=>`${x.date} → ${x.place} → ${x.event}`).join('\n')};
 if(a.kind==='exam')return {kind:'史实与评价',text:'选项 '+('ABCD'[Number(a.answer)]||'未记录')};
 if(a.kind==='evidenceObservation')return {kind:'档案核验',text:(a.answer?.question||'')+' → '+(a.answer?.answer||'')};
 const words={submit:'日方递交',receive:'中方接收',japanese:'日方投降代表席',chinese:'中方受降代表席',document:'降书',pen:'签字用具',notebook:'记者记录本'};
 const kinds={'propActivity:handoff':'交接配对','propActivity:sort':'道具分类','propActivity:record':'观察记录'};
 if(a.kind==='propActivity:record')return {kind:kinds[a.kind],text:'记录核对：'+String(a.choice||'').split('|').map(x=>({sep9:'1945年9月9日',nanjing:'南京原中央军校大礼堂',china:'中国战区受降仪式'}[x]||x)).join(' · ')};
 return {kind:kinds[a.kind]||'学习操作',text:String(a.choice||a.answer||'未记录').split('->').map(x=>words[x]||x).join(' → ')};
}
